const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const figures={figure1:['Figure 1 · Cohort and temporal landscape','Cohort construction, timing of first coded PO-AKI, and perioperative EHR event density. Source: main manuscript, Figure 1.'],figure2:['Figure 2 · STREAM architecture','Original manuscript schematic. The Methods define the index as recorded surgery completion; the pre-index segment can contain intraoperative records.'],figure3:['Figure 3 · Discrimination over time','Mean AUPRC across five fold-specific models. Bands are fold-wise minimum–maximum, not confidence intervals. The secondary axis shows coded PO-AKI prevalence in the remaining risk set.'],figure4:['Figure 4 · Calibration across time','Calibration at surgery completion, 6, 12, 24, 48 hours and day 7. The diagonal indicates perfect calibration. Quantitative results appear in Supplementary Table S6.'],figure5:['Figure 5 · Event-arrival attribution','Code-level mean changes in model logit during the first 7 postoperative days. Error bars show the five-model minimum–maximum range. These are model associations, not causal effects.'],figure6:['Figure 6 · Within-window order sensitivity','Panel A: random order perturbations across 6-hour windows. Panel B: the complete 0–6 h window for an illustrative episode with coded PO-AKI at 5.8 h. The same 46 events occupy the same timestamp positions, with event identities assigned in reverse order.'],s1:['Supplementary Figure S1 · Grouped deletion','Events with the same modality and code are grouped within perioperative periods, removed, and rescored. Attribution is the original minus perturbed model logit.'],s2:['Supplementary Figure S2 · Complementary attribution','Age substitution uses 48 years as reference. Surgery substitution covers 75 types (Spearman ρ = 0.667 with observed incidence). Temporal grouped deletion characterizes period-specific model reliance.'],s3:['Supplementary Figure S3 · Event-arrival case studies','Two illustrative episodes. Red/blue indicate increases/decreases in estimated risk; darker shades identify threshold-crossing updates. Contributions are computed on the logit scale; the plotted trajectory is on the probability scale.'],s4:['Supplementary Figure S4 · Fixed-window case studies','Time-series Transformer predictions for the same two episodes, updated at predefined 6-hour intervals. The 0.50 line is a visualization reference, not a clinically validated alert threshold.']};
const fig=(id,cls='')=>`<button class="fig ${cls}" data-figure="${id}" aria-label="Enlarge ${figures[id][0]}"><span class="expand">Expand ↗</span><img src="assets/${id}.png" alt="${figures[id][0]}" loading="lazy"><span class="figcap">${figures[id][0]} · Click to inspect the original</span></button>`;
const head=(tag,title,desc='')=>`<div class="slide-head"><span class="eyebrow">${tag}</span><h2>${title}</h2>${desc?`<p class="lede">${desc}</p>`:''}</div>`;
const source=(text,id='')=>`<div class="source"><span>${text}</span>${id?`<button data-figure="${id}">View source figure ↗</button>`:''}</div>`;
const slides=[
{id:'opening',title:'Event by event',tag:'Overview',notes:'开场：这项研究关注纵向 EHR 的表示方式。手术结束提供明确的时间锚点，随后临床信息不规则地到达，STREAM 随事件更新 coded PO-AKI 风险。\n三个数字分别是分析队列、手术结束时 AUPRC 和术后按 6 小时窗口宏平均的 AUPRC。注意两个 AUPRC 对应不同评估阶段，不能直接拿它们比较优劣。\n全文以最新正文与补充文档为准。点击左下角或最后的 Evidence library 可查原图和完整表格。',html:`<div class="hero"><div><span class="eyebrow">LONGITUDINAL EHR · DYNAMIC CLINICAL PREDICTION</span><h1>STREAM</h1><p class="subtitle manuscript-title">Sequential Transformer for Risk Estimation from Asynchronous Medical Events for Dynamic Postoperative AKI Prediction</p><div class="actions"><button class="primary" data-go="1">Explore the study →</button><button data-go="7">Jump to results</button></div><p class="byline">Shuyu Lu<br>UTHealth Houston · The University of Texas at Austin</p></div><div class="heroart"><span class="eyebrow">FROM CLINICAL EVENTS TO EVOLVING ESTIMATES</span><svg viewBox="0 0 520 230" role="img" aria-label="Conceptual sequence of irregular events with a surgery anchor and subsequent model updates"><path d="M10 70H510" stroke="#547b7c"/><path d="M200 25V210" stroke="#93b7a9" stroke-dasharray="4 6"/><g fill="#bbd6b8"><circle cx="30" cy="70" r="9"/><circle cx="90" cy="70" r="9"/><circle cx="115" cy="70" r="9"/></g><rect x="177" y="47" width="46" height="46" rx="8" fill="#d4aa5f"/><text x="200" y="120" text-anchor="middle" fill="#e5cd9d" font-size="12">SURGERY END</text><g fill="#79c2a9"><circle cx="265" cy="70" r="9"/><circle cx="290" cy="70" r="9"/><circle cx="365" cy="70" r="9"/><circle cx="390" cy="70" r="9"/><circle cx="475" cy="70" r="9"/></g><path d="M200 180H265V158H290V166H365V135H390V146H475V124H510" fill="none" stroke="#b4e9cf" stroke-width="3"/><g fill="#b4e9cf"><circle cx="200" cy="180" r="4"/><circle cx="265" cy="158" r="4"/><circle cx="290" cy="166" r="4"/><circle cx="365" cy="135" r="4"/><circle cx="390" cy="146" r="4"/><circle cx="475" cy="124" r="4"/></g><text x="10" y="210" fill="#adc4c7" font-size="11">Historical context</text><text x="315" y="210" fill="#adc4c7" font-size="11">Event-by-event updates →</text></svg><div class="hero-facts"><div><b>167,078</b><span>surgical episodes</span></div><div><b>0.771</b><span>surgery-index AUPRC</span></div><div><b>0.589</b><span>dynamic macro-AUPRC</span></div></div><p class="art-note" style="margin-top:20px">Conceptual illustration above · Reported study results below</p></div></div><div class="affiliation-logos" aria-label="Research team and institutions"><img class="logo-team" src="assets/logo-team-ai.png" alt="TEAM-AI: Translational AI Excellence and Applications in Medicine"><img class="logo-uthealth" src="assets/logo-uthealth-houston.png" alt="UTHealth Houston"><img class="logo-dell" src="assets/logo-dell-medical-school.png" alt="The University of Texas at Austin, Dell Medical School"></div>${source('Retrospective study · 30-day coded PO-AKI · Main manuscript, Abstract and Table 2')}`},
{id:'question',title:'Why event streams?',tag:'The question',notes:'先区分三个信息组织方式。静态模型在手术结束时做一次估计；固定窗口把记录归入 6 小时间隔；事件流保留逐条记录以及记录之间的顺序。\n这里的示意图只说明表示方式，不是模拟患者数据。研究用性能比较与顺序置换两种证据分别观察预测能力和顺序敏感性。不能仅凭置换敏感性证明顺序必然提高准确度。',html:head('01 / THE QUESTION','What can be learned between fixed time steps?','Clinical records arrive irregularly. Their timing, repetition and order may carry information that a fixed-window summary does not preserve.')+`<div class="triple"><article class="representation"><span class="number">01 · STATIC</span><h3>One summary</h3><p>Logistic regression and XGBoost estimate risk at the surgery index.</p><svg viewBox="0 0 310 130" aria-hidden="true"><path d="M10 45H295" stroke="#c1cbc3"/><g fill="#bac8bf"><circle cx="25" cy="45" r="5"/><circle cx="60" cy="45" r="5"/><circle cx="83" cy="45" r="5"/><circle cx="165" cy="45" r="5"/></g><rect x="202" y="20" width="70" height="50" rx="4" fill="#dae3d6"/><text x="237" y="50" text-anchor="middle" fill="#142f38" font-size="13">Summary</text><path d="M237 73V100" stroke="#82948a"/><circle cx="237" cy="109" r="7" fill="#14786e"/></svg></article><article class="representation"><span class="number">02 · FIXED WINDOWS</span><h3>One vector per interval</h3><p>LSTM, GRU-D and a Transformer process regular 6-hour positions.</p><svg viewBox="0 0 310 130" aria-hidden="true"><g fill="#e2e8dc" stroke="#bcc9be"><rect x="10" y="28" width="65" height="60"/><rect x="85" y="28" width="65" height="60"/><rect x="160" y="28" width="65" height="60"/><rect x="235" y="28" width="65" height="60"/></g><g fill="#617276" font-size="12" text-anchor="middle"><text x="42" y="112">0–6 h</text><text x="117" y="112">6–12 h</text><text x="192" y="112">12–18 h</text><text x="267" y="112">18–24 h</text></g><path d="M42 58H267" stroke="#82948a" stroke-dasharray="4 5"/></svg></article><article class="representation featured"><span class="number">03 · EVENT STREAM</span><h3>Each recorded event</h3><p>STREAM updates the model estimate whenever a new event enters the sequence.</p><svg viewBox="0 0 310 130" aria-hidden="true"><path d="M10 45H300" stroke="#8ab4a5"/><g fill="#14786e"><circle cx="20" cy="45" r="7"/><circle cx="55" cy="45" r="7"/><circle cx="70" cy="45" r="7"/><circle cx="160" cy="45" r="7"/><circle cx="225" cy="45" r="7"/><circle cx="243" cy="45" r="7"/><circle cx="286" cy="45" r="7"/></g><path d="M20 105H55V88H70V99H160V78H225V88H243V65H286V73H300" fill="none" stroke="#14786e" stroke-width="2"/></svg></article></div><div class="note-box" style="margin-top:25px">Study question: how does retaining individual clinical events support dynamic prediction, and how does their within-window order affect STREAM’s estimates?</div>${source('Main manuscript · Introduction and Discussion. Prior work includes STraTS, Event Stream GPT, Curiosity, BEHRT and Med-BERT.')}`},
{id:'cohort',title:'The study cohort',tag:'Cohort',notes:'数据来自 Memorial Hermann Health System，Cerner EHR 转换为 OMOP CDM 5.4。分析单位是 surgical episode：一次符合条件的非心脏手术，加关联的围术期事件流。患者可以在开发集中贡献多次手术。\n正文报告开发集143,540例和测试集23,538例，coded PO-AKI比例5.7%与10.1%。最终划分比例不等于最初80:20。五折按患者划分，同一患者不跨训练与验证折，也不跨开发和测试集。\n研究起始日期统一为1 January 2014。开发集为1 January 2014至29 August 2022；测试集为30 August 2022至13 April 2024。',html:head('02 / COHORT','167,078 surgical episodes. One clinical anchor.','A retrospective, single-health-system cohort of adult noncardiac surgery, linked to longitudinal OMOP CDM records.')+`<div class="statrow"><div class="stat"><b>134,741</b><span>distinct patients</span></div><div class="stat"><b>10,518</b><span>episodes with coded PO-AKI</span></div><div class="stat"><b>6</b><span>noncardiac surgical categories</span></div></div><div class="split"><div><div class="timeline"><div><span class="eyebrow">DEVELOPMENT · 1 JAN 2014–29 AUG 2022</span><h3>143,540 episodes</h3><p>8,147 with coded PO-AKI <b>(5.7%)</b></p><p class="small" style="margin-top:12px">Five patient-grouped folds</p></div><div class="test"><span class="eyebrow">TEMPORAL TEST · 30 AUG 2022–13 APR 2024</span><h3>23,538 episodes</h3><p>2,371 with coded PO-AKI <b>(10.1%)</b></p><p class="small" style="margin-top:12px">One qualifying surgery per test patient</p></div></div><div class="note-box">Development and test sets contain no shared patients. All five fold-specific models are evaluated on the same held-out test set.</div></div><div class="stack"><h3>From source procedures to eligible surgery</h3><p class="small">768,613 records → 602,871 records in the 200 most frequent procedure types → 167,078 eligible episodes.</p><details><summary>View sequential exclusion counts</summary><div class="risk-table"><div>Noninvasive procedures <b>379,195</b></div><div>Cardiac surgery <b>4,995</b></div><div>Age &lt;18 years <b>10,934</b></div><div>AKI recorded in preceding year <b>6,435</b></div><div>Unknown sex <b>34,234</b></div></div></details><div class="tagrow"><span>Abdominal</span><span>Intracranial</span><span>Thoracic</span><span>Spinal</span><span>Joint</span><span>Skin</span></div></div></div>${source('Main manuscript · Study Cohort Construction and Table 1','figure1')}`},
{id:'landscape',title:'The perioperative landscape',tag:'Clinical context',notes:'这一页说明为什么围术期适合研究动态预测：既有明确的anchor，也有手术附近大量异步事件。图1的事件密度和诊断编码都集中在早期。\n结局是30天coded PO-AKI：ICD-9-CM 584*或ICD-10-CM N17*首次术后记录，不等同于KDIGO生理学定义。事件流在首次诊断处截断，目的是防止结局之后信息进入模型。\n数据是记录时间，不能保证等于疾病真正起始时间。',html:head('03 / CLINICAL CONTEXT','The information stream is densest near surgery.','Recorded PO-AKI diagnoses and clinical activity concentrate early, then become progressively sparser.')+`<div class="split wide">${fig('figure1')}<div class="stack"><div><span class="number">OBSERVATION WINDOW</span><h3>−7 days → surgery end → +30 days</h3></div><div><span class="number">OUTCOME</span><h3>30-day coded PO-AKI</h3><p class="small" style="margin-top:10px">First postoperative ICD-9-CM 584* or ICD-10-CM N17* diagnosis. Positive event streams are truncated at the coded endpoint.</p></div><div class="note-box">A recorded diagnosis marks documentation of AKI. It does not establish the physiologic onset time.</div></div></div>${source('Main manuscript · Figure 1; Outcome Definition; Event Stream Construction')}`},
{id:'representation',title:'Anatomy of an event',tag:'Representation',notes:'从临床记录进入模型：每个事件包含code、modality、relative time、optional value、是否观测到数值和medication boundary。数字值只对年龄与实验室事件使用。\n点击不同token说明其表征。手术结束时放置surgery token，紧随其后放置可学习[BASE]。术中记录没有独立分段，可能包含在pre-index中。\n条件代码映射CCS；药物按RxNorm成分映射，top90%频次保留；21项实验室类型独立保留；手术用SNOMED CT。',html:head('04 / REPRESENTATION','One sequence. Heterogeneous clinical information.','Event identity is combined with modality, timing, numerical values and medication boundaries.')+`<div class="tokens" role="group" aria-label="Explore event types"><button class="token" data-token="demo" aria-pressed="true">AGE · SEX · RACE</button><button class="token" data-token="cond" aria-pressed="false">CCS</button><button class="token med" data-token="med" aria-pressed="false">RxCUI</button><button class="token lab" data-token="lab" aria-pressed="false">LAB</button><button class="token" data-token="surgery" aria-pressed="false">SURGERY</button><button class="token base" data-token="base" aria-pressed="false">[BASE]</button><button class="token post" data-token="post" aria-pressed="false">eₛ₊₁ … eₙ →</button></div><div class="split"><div class="stack"><div class="formula">eᵢ = (cᵢ, mᵢ, tᵢ, vᵢ, oᵢ, bᵢ)<small>code · modality · relative time · numerical value · observation indicator · medication boundary</small></div><div class="formula">xᵢ = E꜀(cᵢ) + Eₘ(mᵢ) + Eᵦ(bᵢ)<br> + fₜ(tᵢ) + fᵥ(cᵢ, vᵢ, oᵢ)<small>Embeddings and continuous-feature projections are learned jointly.</small></div></div><div><div id="tokenDetail" class="note-box"></div><div class="arch-config"><div><b>128</b>hidden dimensions</div><div><b>2</b>Transformer layers</div><div><b>4</b>attention heads</div></div><div class="actions"><button data-figure="figure2">View architecture ↗</button></div></div></div>${source('Main manuscript · Model Architecture; Supplementary Tables S1–S2')}`},
{id:'attention',title:'Which events can be seen?',tag:'Architecture',notes:'点击矩阵任意一行，展示该位置能够访问的信息。这里是基于文稿mask规则的示意，不是训练后attention权重。\nPre-index包含手术结束之前的记录和surgery token，它们之间双向注意力；[BASE]读取所有pre-index和自身；postoperative位置只能读取[BASE]以及当前和过去的术后位置。因此术后上下文通过[BASE]接入既往病史。\n突出专用[BASE]同时服务baseline估计与动态预测，是消融中有支持的结构贡献。',html:head('05 / ARCHITECTURE','A surgery-index summary connects history to follow-up.','Select a query row to explore the structured attention mask. This is an architectural schematic, not learned attention weights.')+`<div class="matrix-layout"><div><div class="mini-label" style="margin-bottom:12px">QUERY ROW ↓ · AVAILABLE KEY POSITIONS →</div><div id="attentionMatrix" class="matrix"></div><div class="legend"><span><i></i>Visible to selected query</span><span><i style="background:#e2e5df"></i>Masked</span><span><i style="background:#d8b469"></i>[BASE] self-attention</span></div></div><div class="stack"><div id="attentionExplanation"></div><div class="note-box">The anchor is recorded surgery completion. The pre-index segment can include intraoperative records; no separate intraoperative segment was modeled.</div><button data-figure="figure2">Inspect the original architecture figure ↗</button></div></div>${source('Main manuscript · Structured block attention mask; Figure 2')}`},
{id:'training',title:'Training and fair comparison',tag:'Study design',notes:'三个损失权重来自Supplementary Table S2：online1.0，baseline0.3，MEM0.01。MEM遮盖15% pre-index codes。checkpoint选择0.9×动态macro AUPRC +0.1×baseline AUPRC。\n静态模型LR和XGBoost；序列模型LSTM、GRU-D、Time-series Transformer。固定窗口149位置=28 pre-index+1 baseline+120 post，每步548维。\n所有模型预测相同30天coded结局。动态评价在同一6小时网格上，STREAM取到该点最近的预测，无新事件时carry forward。[BASE]在第一个post事件前carry forward。\nrisk set包括尚无coded PO-AKI的episode；其中未来30天内发生编码者为positive。宏平均对有效interval等权，而非把全部预测混在一起算。',html:head('06 / STUDY DESIGN','A common target. A common evaluation clock.','Models share the held-out cohort and 30-day coded outcome. Dynamic predictions are compared on the same 6-hour grid.')+`<div class="split"><div class="losses"><div class="loss"><b>1.0</b><div><h3>Postoperative online loss</h3><p>Binary cross-entropy at valid postoperative event positions.</p></div></div><div class="loss"><b>0.3</b><div><h3>Surgery-index loss</h3><p>Explicit supervision for the [BASE] risk estimate.</p></div></div><div class="loss"><b>0.01</b><div><h3>Masked event modeling</h3><p>Reconstruct 15% of eligible masked pre-index event codes.</p></div></div><p class="small">AdamW · learning rate 10⁻⁴ · batch size 16 · dropout 0.2</p></div><div class="stack"><div class="formula">149 positions × 548 features<small>Fixed-window baselines: 28 pre-index + 1 baseline + 120 postoperative positions. LSTM / GRU-D / Time-series Transformer.</small></div><div class="note-box"><b>At each evaluation time:</b> retain episodes still free of coded PO-AKI; label positive if a qualifying diagnosis occurs later by postoperative day 30.</div><p class="small">Interval-specific AUPRC → unweighted mean across valid intervals. STREAM uses the most recent available event prediction at each grid point.</p><button data-table="Algorithm 1">Open unified baseline pseudocode ↗</button></div></div>${source('Main manuscript · Training and Evaluation; Supplementary Algorithm 1 and Table S2')}`},
{id:'performance',title:'Predictive performance',tag:'Results',notes:'Table2报告百分数，这里转换成0–1便于比较。可切换baseline AUPRC、dynamic macro AUPRC和两种AUROC。\nSTREAM baseline AUPRC为0.7714，TS Transformer为0.7288，差4.26个百分点。Dynamic macro AUPRC为0.5886，强动态比较模型GRU-D为0.5470，差4.16个百分点。不要把macro AUROC四舍五入相同0.948描述成完全相等，原表为0.9482和0.9476。\n所有数字是五个fold-specific模型在同一测试集上的均值。范围是模型间min–max，不是统计置信区间或显著性检验。',html:head('07 / PRIMARY RESULTS','STREAM leads both prediction stages.','Explore the means across five fold-specific models from Table 2. Static models are evaluated only at the surgery index.')+`<div class="selectrow" id="metricTabs"><button data-metric="basepr" class="active">Surgery-index AUPRC</button><button data-metric="dynpr">Dynamic macro-AUPRC</button><button data-metric="baseroc">Surgery-index AUROC</button><button data-metric="dynroc">Dynamic macro-AUROC</button></div><div class="split wide"><div><div id="performanceBars"></div><div class="chart-axis"><span>0</span><span>0.25</span><span>0.50</span><span>0.75</span><span>1.00</span></div><p class="small" style="margin-top:25px">Held-out temporal test set · n = 23,538<br>Numbers are proportions; manuscript tables report percentages.</p></div><div id="metricSummary" class="metric-summary"></div></div><div class="actions"><button data-table="Table 2.">Full table and fold ranges ↗</button><button data-table="Supplementary Table S4">All classification metrics ↗</button></div>${source('Main manuscript · Table 2; Supplementary Tables S4–S5')}`},
{id:'temporal',title:'Performance across time',tag:'Results',notes:'这里使用原始图3，避免从图像重新拟合或虚构逐时间点数值。早期48小时STREAM AUPRC约0.75–0.79；TS Transformer约0.72–0.75。\n后期阳性样本数和EHR新增密度下降，AUPRC也随之下降并更波动。不同时间风险集和prevalence不一致，因此不要把曲线下降直接解释成模型退化。\n阴影范围是fold min–max；后期<100个positive episode另有灰色区域。',html:head('08 / PERFORMANCE OVER TIME','The clearest separation occurs early after surgery.','Discrimination is evaluated repeatedly in a changing population of episodes still free of coded PO-AKI.')+`${fig('figure3')}<div class="triple" style="margin-top:25px"><div><span class="number">FIRST 48 HOURS</span><h3>≈0.75–0.79 AUPRC</h3><p class="small" style="margin-top:10px">STREAM maintains the highest reported AUPRC during the event-dense early period.</p></div><div><span class="number">LATER FOLLOW-UP</span><h3>Fewer future positives</h3><p class="small" style="margin-top:10px">Differences become less consistent as observations and remaining positive episodes become sparse.</p></div><div><span class="number">READING THE FIGURE</span><h3>Changing risk sets</h3><p class="small" style="margin-top:10px">The dashed secondary-axis curve shows coded PO-AKI prevalence in the remaining risk set.</p></div></div>${source('Main manuscript · Figure 3 and Predictive Performance Results')}`},
{id:'calibration',title:'Calibration across time',tag:'Calibration',notes:'校准回答预测概率是否对应观察发生率。不要用更低Brier简单证明所有校准维度更好。STREAM在0、6、12、24、48小时和7天均有最低Brier，但其calibration slope约0.65–0.72，理想值为1，仍有miscalibration。\n点击时间切换表S6。Brier skill score相对于该时刻的prevalence-only预测。不同时间prevalence下降，不能只看Brier跨时间下降就判断校准改善。\nS6 baseline的future positives为2,368，队列表为2,371。页面按各表原数保留，但需要解释t=0边界。',html:head('09 / CALIBRATION','Risk probabilities carry information beyond ranking.','STREAM has the lowest reported Brier score at each evaluated time point, while calibration remains imperfect.')+`<div class="selectrow" id="calTabs">${['0 h','6 h','12 h','24 h','48 h','7 d'].map((x,i)=>`<button data-cal="${i}" class="${i===1?'active':''}">${x}</button>`).join('')}</div><div id="brierGrid" class="brier-grid"></div><div class="split" style="margin-top:28px"><div id="calDetail" class="stack"></div><div class="note-box"><b>Ideal calibration:</b> intercept 0, slope 1.<br>STREAM’s reported slopes are 0.65–0.72 across these time points. External validation and recalibration remain necessary before clinical use.</div></div><div class="actions"><button data-figure="figure4">Explore calibration curves ↗</button><button data-table="Supplementary Table S6">Complete calibration metrics ↗</button></div>${source('Supplementary Table S6 · Five-fold means; lower Brier score is better')}`},
{id:'ablation',title:'What matters to the model?',tag:'Ablation',notes:'消融区分architecture、objective和modality。点击切换baseline/dynamic查看同一变体在不同任务下的影响。\n去掉medication最明显，dynamic0.5886到0.2310。条件事件去掉也明显。专用BASE换成surgery token是architecture层面最大动态下降（2.91个百分点）。\n注意time encoding去掉后动态略增，不应声称所有组件必然提高性能。No baseline loss没有训练baseline head，其极低baseline AUPRC不是正常竞争结果。\n表中差值有原文的未四舍五入配对差值，因此可能与已四舍五入均值相减差0.01个百分点。',html:head('10 / ABLATION','Medication context and a dedicated baseline state matter.','Single-component ablations reveal different dependencies at surgery completion and during postoperative updating.')+`<div class="selectrow"><button class="active" data-ablation="dynamic">Dynamic macro-AUPRC</button><button data-ablation="baseline">Surgery-index AUPRC</button></div><div class="split wide"><div><div class="ablation-head"><span>VARIANT</span><span>AUPRC · CHANGE IN PERCENTAGE POINTS</span></div><div id="ablationBars"></div></div><div class="stack"><div class="note-box"><b>Largest input effect:</b> removing medication events reduces dynamic macro-AUPRC from 0.589 to 0.231.</div><div class="note-box"><b>Largest architecture effect:</b> replacing [BASE] with the surgery token reduces dynamic macro-AUPRC to 0.560.</div><p class="small">Removing time encoding did not reduce dynamic macro-AUPRC in this evaluation. The no-baseline-loss variant left the surgery-index head untrained.</p></div></div>${source('Main manuscript · Table 3; Supplementary Tables S7–S8')}`},
{id:'attribution',title:'Interpret individual arrivals',tag:'Interpretability',notes:'事件到达归因是相邻online状态的logit差，首次post事件以前一BASE作为参考。正值为模型估计风险增加，负值为降低。\n临床解释一：其他肾脏和输尿管疾病、伴并发症的糖尿病及高血压出现后，模型上调风险。这与肾脏、代谢和血管易感性的临床背景相符。ADQI/POQI共识将肾功能受损、糖尿病、高血压列为PO-AKI风险因素；具体归因方向仍来自本研究Figure 5。\n临床解释二：妊娠期出血、氨甲环酸、咪达唑仑和罗哌卡因等记录可能标记出血、麻醉及围术期诊疗场景。用药归因还可能反映适应证、手术类型和同时记录的病情，不能直接认定药物造成肾损伤。\n临床解释三：子宫内膜异位症、卵巢囊肿及生育管理相关代码多对应风险下调，可能反映本队列中特定患者群体和诊疗路径。负向更新相对于前一预测状态，并不等于生物学保护作用；妊娠期出血出现在正向结果中，也说明不能把所有妇产科记录概括为低风险。\n同一时间戳事件对最多20个组内置换求边际logit均值。分析限制在术后7天，code至少50位患者（至少一折），并要求五折方向一致。',html:head('11 / EVENT-ARRIVAL ATTRIBUTION','Which newly recorded information changes the estimate?','Clinical patterns help interpret how newly recorded events change STREAM’s estimate. Select a theme to explore the results.')+`<div class="attribution-layout"><div>${fig('figure5')}<p class="small attribution-key"><b>Positive Δlogit:</b> increased model-estimated risk. <b>Negative Δlogit:</b> decreased model-estimated risk.</p></div><aside class="clinical-panel"><span class="eyebrow">CLINICAL READING OF FIGURE 5</span><div class="selectrow clinical-tabs" aria-label="Clinical interpretation themes"><button class="active" aria-pressed="true" data-clinical="vulnerability">Comorbidities</button><button aria-pressed="false" data-clinical="care">Perioperative care</button><button aria-pressed="false" data-clinical="casemix">Patient groups</button></div><div id="clinicalInterpretation" aria-live="polite"></div><details class="attribution-method"><summary>How attribution was calculated</summary><div class="formula">Δzᵢ = zᵢ − zᵢ₋₁<small>The first postoperative event is compared with [BASE]. Tied-timestamp contributions are averaged across sampled event orders.</small></div></details><p class="small clinical-scope">Clinical interpretations describe learned associations; they do not estimate causal effects.</p></aside></div>${source('Main manuscript · Figure 5 and Event-Arrival Attribution Methods · First 7 postoperative days; concordant direction across five models')}`},
{id:'cases',title:'Follow individual trajectories',tag:'Case studies',notes:'两个个例是说明机制，不是population-level证据。先选择患者，再切换STREAM或time-series Transformer，比较同一患者的两种更新方式。\n点击关键时点，原始图中对应列会被高亮；可用前后按钮逐步讲解。所有曲线与柱子均来自原始图，没有推算或插值患者数据。\n腹腔镜阑尾切除个例首次coded AKI在15.4小时；剖腹探查个例30天内没有coded AKI。STREAM红蓝表示模型估计风险增加或减少，深色表示该次更新跨过0.50阈值。单个事件的柱子表示纳入该事件后的概率；同一时刻的总体轨迹来自更新后的logit再经sigmoid转为概率。',html:head('12 / PATIENT-LEVEL EXAMPLES','Follow the patient, one update at a time.','Choose an episode and model, then select a landmark to highlight it in the original trajectory.')+`<div class="case-toolbar"><div class="selectrow" aria-label="Select patient"><button class="active" aria-pressed="true" data-patient="positive">PO-AKI-positive · Appendectomy</button><button aria-pressed="false" data-patient="negative">PO-AKI-negative · Laparotomy</button></div><div class="selectrow" aria-label="Select model"><button class="active" aria-pressed="true" data-case="s3">STREAM</button><button aria-pressed="false" data-case="s4">Time-series Transformer</button></div></div><div class="patient-layout"><div><div id="patientFigure" class="patient-figure"></div><div id="caseLandmarks" class="landmark-buttons" aria-label="Select trajectory landmark"></div><div class="landmark-controls"><button id="casePrev" aria-label="Previous landmark">← Previous</button><span id="casePosition"></span><button id="caseNext" aria-label="Next landmark">Next →</button></div></div><aside class="patient-insight"><span class="eyebrow" id="patientBadge"></span><h3 id="patientTitle"></h3><p id="patientOutcome" class="small"></p><div id="landmarkInfo" aria-live="polite"></div><p id="patientLegend" class="small"></p><button id="caseOriginal">Open complete source figure ↗</button></aside></div>${source('Supplementary Figures S3–S4 · Original trajectories with interactive landmark highlights')}`},
{id:'order',title:'Does order change prediction?',tag:'Order sensitivity',notes:'同6小时窗口内保留所有event内容和timestamp slots，但重新分配event到各位置。这个实验改变事件-时间对应关系，用平均absolute logit difference衡量敏感性。\n点击热图单元可查看精确中位数和窗口数。0–6小时从3–4 events中位0.25到≥33 events中位0.48。其他时间段不是严格单调，不要过度概括。\n区分两种置换：within-window变换细粒度顺序；within-timestamp只处理未知的相同时刻先后。S9后者median0.032。\n切换Individual example查看完整0–6小时窗口。首次coded PO-AKI在5.8小时，图中保留这一时间标记。相同46条事件与时间槽，事件身份按反序分配。6小时末原始顺序概率1.00、反序0.02，absolute logit change为10.12。这个个例说明顺序扰动对模型轨迹的影响。',html:head('13 / WITHIN-WINDOW ORDER','The same events can lead to different predictions.','Explore population-level sensitivity and an individual 0–6 h reversal example using the same events and timestamp positions.')+`<div class="selectrow" aria-label="Order sensitivity views"><button class="active" aria-pressed="true" data-order-view="population">Population sensitivity</button><button aria-pressed="false" data-order-view="individual">Individual example · 0–6 h</button></div><div id="orderPopulation"><div class="split wide"><div><div id="heatmap" class="heatmap"></div><div class="legend"><span>Median absolute change in end-of-window logit</span><span>n = contributing windows</span></div></div><div class="stack"><div id="heatDetail"></div><div class="note-box">Windows with ≥33 events show median sensitivities of 0.40–0.50 across time strata. The relationship is not strictly monotonic in every stratum.</div><p class="small">Up to 20 permutations per window. Sensitivity measures model dependence on ordering; it does not by itself establish better predictive accuracy.</p></div></div></div><div id="orderIndividual" class="reversal-layout" hidden><div class="reversal-figure"><svg viewBox="1135 42 910 980" role="img" aria-label="Figure 6b: original and reversed event-order trajectories during the first 6 hours, with coded AKI at 5.8 hours"><defs><clipPath id="reversalCrop"><rect x="1135" y="42" width="910" height="980"/></clipPath></defs><image href="assets/figure6.png" x="0" y="0" width="2048" height="1033" clip-path="url(#reversalCrop)"/></svg></div><aside class="stack"><span class="eyebrow">ONE EPISODE · 46 EVENTS</span><h3>Same events.<br>Different arrival order.</h3><div class="risk-table"><div>Displayed window <b>0–6 h</b></div><div>First coded PO-AKI <b>5.8 h</b></div></div><div class="reversal-scores"><div><span>Original order · at 6 h</span><b>1.00</b></div><div><span>Reversed order · at 6 h</span><b>0.02</b></div></div><div class="note-box"><b>|Δlogit| at 6 h = 10.12</b><br>The same clinical events and timestamp positions were retained; event identities were assigned in reverse temporal order.</div><p class="small">The full first 6 hours are shown, including the coded PO-AKI marker at 5.8 h. The lower panel shows event counts per 0.25 h.</p></aside></div><div class="actions"><button data-figure="figure6">Original heatmap and reversal example ↗</button><button data-table="Supplementary Table S9">Within-timestamp robustness ↗</button></div>${source('Main manuscript · Figure 6a–b; Supplementary Table S9')}`},
{id:'complementary',title:'Connect temporal scales',tag:'Additional interpretation',notes:'这一页把三类扰动结果放回临床背景。Age：固定其他输入，仅改变年龄时，baseline估计随年龄单调增加。这与老龄患者更容易发生PO-AKI的临床认识相符，但不能把曲线视为真实患者随年龄增长的自然病程。最新原图以48岁为参考。\nProcedure：剖腹探查和大肠切除位于较高替换logit与较高观察发生率区域；膝关节镜和肩袖修复位于较低区域。这个排序可能同时携带手术负担、适应证及患者选择的信息。75类手术的相关性rho=0.667表明经验一致性，不是替换手术的治疗效应。\nGrouped deletion：伴并发症糖尿病、其他肾脏和输尿管疾病、呼吸衰竭及休克等在不同窗口出现正向依赖，说明模型利用共病与急性病情的时间背景。肾脏疾病在手术前48小时的贡献较突出。急性心肌梗死在图中却呈负向，必须按条件关联来解释，不能说其保护肾脏；还需结合代码时序、共现事件及编码方式核查。\n事件到达与grouped deletion在共同replicated codes中的rho=0.822、91.9%方向一致，表明即时更新与较宽时间窗的依赖具有一致性。仅适用于双方均筛选通过的重叠code。',html:head('14 / COMPLEMENTARY INTERPRETATION','Place model reliance in its clinical context.','Age, procedure identity and repeated clinical records offer complementary views of the information used by STREAM.')+`<div class="attribution-layout complementary-layout"><div>${fig('s2')}<div class="concordance-strip"><span><b>ρ = 0.822</b> Arrival ↔ grouped deletion</span><span><b>91.9%</b> Directional agreement</span></div><p class="small" style="margin-top:9px">Among overlapping replicated codes.</p></div><aside class="clinical-panel"><span class="eyebrow">CLINICAL READING OF FIGURE S2</span><div class="selectrow clinical-tabs" aria-label="Complementary interpretation themes"><button class="active" aria-pressed="true" data-complementary="age">Age</button><button aria-pressed="false" data-complementary="procedure">Procedure</button><button aria-pressed="false" data-complementary="history">Clinical history</button><button aria-pressed="false" data-complementary="agreement">Agreement</button></div><div id="complementaryInterpretation" aria-live="polite"></div><button class="grouped-method-btn" data-figure="s1">How grouped deletion works ↗</button><p class="small clinical-scope">Perturbation estimates characterize model reliance under the observed clinical context.</p></aside></div>${source('Main manuscript · Complementary Attribution; Supplementary Figures S1–S2')}`},
{id:'meaning',title:'Scope and next steps',tag:'Interpretation',notes:'总结时保留边界：单中心retrospective、coded而非KDIGO、死亡非competing event、晚期positive稀少、记录与临床时间差。\n预测准确并不等于临床效益，0.5不是已验证预警阈值，下一步需要external validation、校准、工作流与false-alert burden验证。\nDigital twin只作为未来risk-estimation component；本研究不是generative patient simulator，也没有验证治疗反事实。标准词表提供跨机构适配的基础，不代表迁移已经成立。',html:head('15 / INTERPRETATION','A foundation for dynamic risk estimation, with clear limits.','The study supports an event-stream representation for this task. Clinical deployment and cross-system transfer remain future evaluations.')+`<div class="limits"><article><span class="number">GENERALIZATION</span><h3>One health system</h3><p>Retrospective temporal validation supports within-system evaluation. External institutions and new clinical domains remain untested.</p></article><article><span class="number">OUTCOME</span><h3>Documented coded AKI</h3><p>Diagnosis codes may undercapture physiologic KDIGO-defined injury. Death was not modeled as a competing event.</p></article><article><span class="number">TIME AND OBSERVATION</span><h3>Clinical records are imperfect clocks</h3><p>Tied timestamps and changing observation density affect interpretation. Later intervals have fewer positive episodes.</p></article><article><span class="number">CLINICAL USE</span><h3>Prospective utility is still open</h3><p>Alert thresholds, false-alert burden, workflow integration, recalibration and decision impact require evaluation.</p></article></div><div class="note-box" style="margin-top:20px"><b>Potential digital-twin contribution:</b> an event-updated, interpretable risk-estimation component for future perioperative digital twins. Patient simulation and treatment-effect prediction were not evaluated.</div>${source('Main manuscript · Abstract, Discussion and Limitations')}`},
{id:'takeaways',title:'What this study adds',tag:'Takeaways',notes:'结束时回到三个核心点：保留事件级结构、验证双阶段动态预测、检查信息与顺序怎样改变模型输出。\n在这一单中心coded PO-AKI任务中，STREAM的预测表现和解释分析支持进一步研究事件流建模。未来仍需跨机构与前瞻性验证。\n作者顺序、学位及单位按最新稿件首页呈现。Xiaomeng Wang有两个单位；Xiaoyang Ruan与Hongfang Liu为通讯作者。',html:`<div class="conclusion-layout"><div class="conclusion-top"><div class="closing"><span class="eyebrow">STREAM / THE TAKEAWAY</span><h2>Preserve the event.<br>Update the estimate.<br>Examine the sequence.</h2><p>Longitudinal clinical context supports dynamic, interpretable prediction of coded PO-AKI.</p><button class="primary" data-go="17">Explore the evidence →</button></div><div class="conclusion-results"><div><b>0.771</b><span>Surgery-index AUPRC</span></div><div><b>0.589</b><span>Dynamic macro-AUPRC</span></div><div><b>Event-level</b><span>Interpretation over time</span></div></div></div><div class="author-panel"><span class="eyebrow">AUTHORS & AFFILIATIONS</span><p class="author-byline"><span class="author-name">Shuyu Lu MS<sup>1</sup></span>, <span class="author-name">Xiaoyang Ruan PhD<sup>2,*</sup></span>, <span class="author-name">Liwei Wang MD, PhD<sup>2</sup></span>, <span class="author-name">Jaerong Ahn PhD<sup>2</sup></span>, <span class="author-name">Andrew Wen MS<sup>2</sup></span>, <span class="author-name">Jun Jiang PhD<sup>2</sup></span>, <span class="author-name">Xiaomeng Wang MS<sup>1,2</sup></span>, <span class="author-name">Yafen Liang MD, PhD<sup>3</sup></span>, <span class="author-name">Hongfang Liu PhD<sup>2,*</sup></span></p><div class="institution-key"><p><b>1</b> McWilliams School of Biomedical Informatics, The University of Texas Health Science Center at Houston</p><p><b>2</b> Department of Quantitative and Systems Health Sciences, Dell Medical School, The University of Texas at Austin</p><p><b>3</b> Department of Anesthesiology, Critical Care and Pain Medicine, McGovern Medical School, The University of Texas Health Science Center at Houston</p><p><b>*</b> Corresponding authors</p></div></div></div>${source('Main manuscript · Author information, Abstract and Tables 2–3')}`},
{id:'library',title:'Evidence library',tag:'Appendix',notes:'这里汇集最新两个Word稿件中提取的13个表（含统一伪代码）、10张图、35条参考文献。表格原文保留；数字格式有百分数和0–1差异，以各表说明为准。\n演示页面所有重绘图均使用原表数字，或明确标记为conceptual。完整原图可放大；此公开展示版本不提供Word稿件下载。\n投稿前核对：S6 baseline positives2368与Table1的2371；正文部分preoperative旧词仍未统一；S3柱图几何与caption的解释。',html:head('APPENDIX / EVIDENCE LIBRARY','The full evidence is one click away.','Original figures, complete tables, model pseudocode and manuscript references.')+`<div class="selectrow" id="libraryTabs"><button class="active" data-library="tables">Tables & algorithm</button><button data-library="figures">All 10 figures</button><button data-library="references">References</button></div><div id="libraryTableControls" class="library-controls"><label class="sr-only" for="tableSelect">Choose a table</label><select id="tableSelect"></select><label class="sr-only" for="tableSearch">Filter table rows</label><input id="tableSearch" placeholder="Filter rows…" type="search"></div><div id="libraryContent" class="library-content"></div><div class="actions"><a class="document-link" href="https://github.com/Frank-LSY/STREAM-PO-AKI" target="_blank" rel="noopener">Study code ↗</a><button class="print-btn" id="printBtn">Print presentation</button></div>${source('Source: the two manuscript files supplied for this presentation · Tables and references retain source wording')}`}
];
$('#main').innerHTML=slides.map((s,i)=>`<section class="slide" data-id="${s.id}" aria-label="Chapter ${i+1}: ${s.title}" tabindex="-1">${s.html}</section>`).join('');
let current=0,reading=false,observer;const total=slides.length;
function go(i,push=true){current=Math.max(0,Math.min(total-1,i));$$('.slide').forEach((el,k)=>el.classList.toggle('active',k===current));$('#counter').textContent=`${String(current+1).padStart(2,'0')} / ${total}`;$('#sectionLabel').textContent=slides[current].tag+' / '+slides[current].title;$('#progress').style.width=((current+1)/total*100)+'%';$('#prevBtn').disabled=current===0;$('#nextBtn').disabled=current===total-1;$('#notesText').innerHTML=slides[current].notes.split('\n').map(x=>`<p>${x}</p>`).join('');if(push)history.replaceState(null,'','#'+(current+1));if(reading){document.querySelectorAll('.slide')[current].scrollIntoView({behavior:'smooth',block:'start'});}else window.scrollTo(0,0);}
$('#prevBtn').onclick=()=>go(current-1);$('#nextBtn').onclick=()=>go(current+1);
function openOverview(){ $('#chapterGrid').innerHTML=slides.map((s,i)=>`<button data-chapter="${i}" class="${i===current?'active':''}"><span>${String(i+1).padStart(2,'0')} / ${s.tag.toUpperCase()}</span>${s.title}</button>`).join('');$('#overview').showModal();}
$('#overviewBtn').onclick=openOverview;
function toggleNotes(){let open=$('#notes').hidden;$('#notes').hidden=!open;$('#notesBtn').setAttribute('aria-pressed',String(open));}$('#notesBtn').onclick=toggleNotes;$('#closeNotes').onclick=toggleNotes;
$('#modeBtn').onclick=()=>{reading=!reading;document.body.classList.toggle('reading',reading);$('#modeBtn').textContent=reading?'Presentation view':'Reading view';$('#modeBtn').setAttribute('aria-pressed',String(reading));go(current,false);};
$('#fullBtn').onclick=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch(e){$('#fullBtn').title='Full screen is unavailable in this browser';}};
function showFigure(id){let f=figures[id];$('#evidenceTitle').textContent=f[0];$('#evidenceCaption').textContent=f[1];$('#evidenceImage').src=`assets/${id}.png`;$('#evidenceImage').alt=f[0];$('#imageLink').href=`assets/${id}.png`;$('.image-stage').classList.remove('zoomed');$('#zoomBtn').textContent='Zoom in';$('#evidence').showModal();}
$('#zoomBtn').onclick=()=>{let on=$('.image-stage').classList.toggle('zoomed');$('#zoomBtn').textContent=on?'Fit image':'Zoom in';};
document.addEventListener('click',e=>{const f=e.target.closest('[data-figure]');if(f)showFigure(f.dataset.figure);const g=e.target.closest('[data-go]');if(g)go(+g.dataset.go);const ch=e.target.closest('[data-chapter]');if(ch){$('#overview').close();go(+ch.dataset.chapter);}const cl=e.target.closest('[data-close]');if(cl)cl.closest('dialog').close();const tb=e.target.closest('[data-table]');if(tb)openTable(tb.dataset.table);});
